INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scientist', 'n.', '/ˈsaɪəntɪst/', '科学家', 'Zhong Yang was a scientist who gave his life to studying plants.', '钟扬是一位献身于植物研究的科学家。', 'Scientists', 1, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a famous scientist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scientific', 'adj.', '/ˌsaɪənˈtɪfɪk/', '科学的；与科学有关的', 'Franklin spent her life on scientific research.', '富兰克林一生都投身于科学研究。', 'Scientists', 2, 0, 'senior', 'wordlist', 'elective2', 'U1', 'scientific research', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advance', 'n./v.', '/ədˈvɑːns/', '进步，进展；前进', 'Her work led to a major advance in our understanding of DNA.', '她的工作使我们对DNA的理解取得了重大进展。', 'Scientists', 3, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a major advance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'passion', 'n.', '/ˈpæʃn/', '酷爱；热情', 'She had an undying passion for science all her life.', '她一生都对科学怀有不灭的酷爱。', 'Scientists', 4, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a passion for science', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'publish', 'v.', '/ˈpʌblɪʃ/', '发表；出版', 'By the age of 26, Franklin had published five papers.', '到26岁时，富兰克林已经发表了五篇论文。', 'Scientists', 5, 0, 'senior', 'wordlist', 'elective2', 'U1', 'publish a paper', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'master', 'v.', '/ˈmɑːstə(r)/', '掌握；精通', 'In Paris she mastered a special X-ray technique.', '在巴黎她精通了一种特殊的X射线技术。', 'Scientists', 6, 0, 'senior', 'wordlist', 'elective2', 'U1', 'master a skill', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'assign', 'v.', '/əˈsaɪn/', '分配；分派（工作、任务）', 'Franklin was assigned to study the structure of DNA.', '富兰克林被分派去研究DNA的结构。', 'Scientists', 7, 0, 'senior', 'wordlist', 'elective2', 'U1', 'be assigned to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'unnoticed', 'adj.', '/ʌnˈnəʊtɪst/', '未被注意的；被忽视的', 'For a long time her important work went unnoticed.', '在很长一段时间里，她重要的工作都未受到注意。', 'Scientists', 8, 0, 'senior', 'wordlist', 'elective2', 'U1', 'go unnoticed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'female', 'adj.', '/ˈfiːmeɪl/', '女性的；雌性的', 'As the only female scientist on the project, she worked alone.', '作为项目里唯一的女性科学家，她独自工作。', 'Scientists', 9, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a female scientist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'evidence', 'n.', '/ˈevɪdəns/', '证据；根据', 'She was careful and wanted more evidence before speaking.', '她很谨慎，发言前想要更多的证据。', 'Scientists', 10, 0, 'senior', 'wordlist', 'elective2', 'U1', 'look for evidence', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'data', 'n.', '/ˈdeɪtə/', '数据；资料', 'Two other scientists got hold of her data without asking.', '另外两位科学家未经允许就拿到了她的数据。', 'Scientists', 11, 0, 'senior', 'wordlist', 'elective2', 'U1', 'collect data', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'virus', 'n.', '/ˈvaɪrəs/', '病毒', 'Later Franklin began her famous work on viruses.', '后来富兰克林开始了她著名的病毒研究。', 'Scientists', 12, 0, 'senior', 'wordlist', 'elective2', 'U1', 'study a virus', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'credit', 'n.', '/ˈkredɪt/', '赞扬；认可', 'Franklin received little credit for her key discovery.', '富兰克林为她关键的发现几乎没有得到认可。', 'Scientists', 13, 0, 'senior', 'wordlist', 'elective2', 'U1', 'receive credit', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crucial', 'adj.', '/ˈkruːʃl/', '至关重要的；关键的', 'She had provided the crucial information about DNA.', '她提供了关于DNA的至关重要的信息。', 'Scientists', 14, 0, 'senior', 'wordlist', 'elective2', 'U1', 'play a crucial role', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'breakthrough', 'n.', '/ˈbreɪkθruː/', '突破；重大进展', 'Her photograph allowed them to make a breakthrough.', '她的照片让他们取得了突破。', 'Scientists', 15, 0, 'senior', 'wordlist', 'elective2', 'U1', 'make a breakthrough', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fellow', 'adj.', '/ˈfeləʊ/', '同伴的；同行的', 'She was not always respected by her fellow scientists.', '她并不总是受到同行科学家的尊重。', 'Scientists', 16, 0, 'senior', 'wordlist', 'elective2', 'U1', 'fellow scientists', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gender', 'n.', '/ˈdʒendə(r)/', '性别', 'One of her biggest problems was gender inequality.', '她最大的问题之一就是性别不平等。', 'Scientists', 17, 0, 'senior', 'wordlist', 'elective2', 'U1', 'gender inequality', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'inequality', 'n.', '/ˌɪnɪˈkwɒləti/', '不平等；不平衡', 'She faced inequality but never lost heart.', '她面对不平等，却从未灰心。', 'Scientists', 18, 0, 'senior', 'wordlist', 'elective2', 'U1', 'social inequality', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'unfair', 'adj.', '/ˌʌnˈfeə(r)/', '不公平的；不公正的', 'Women in science often received unfair treatment then.', '当时科学界的女性常常受到不公平对待。', 'Scientists', 19, 0, 'senior', 'wordlist', 'elective2', 'U1', 'unfair treatment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'earn', 'v.', '/ɜːn/', '赢得，博得；挣得', 'In 1945 she earned her doctorate in chemistry.', '1945年她获得了化学博士学位。', 'Scientists', 20, 0, 'senior', 'wordlist', 'elective2', 'U1', 'earn a degree', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'owe', 'v.', '/əʊ/', '归功于；欠', 'We owe this rich seed bank to Zhong Yang.', '我们把这座丰富的种子库归功于钟扬。', 'Scientists', 21, 0, 'senior', 'wordlist', 'elective2', 'U1', 'owe sth to sb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'biology', 'n.', '/baɪˈɒlədʒi/', '生物学', 'Zhong Yang was a professor of biology.', '钟扬是一位生物学教授。', 'Scientists', 22, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a professor of biology', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plateau', 'n.', '/ˈplætəʊ/', '高原', 'Most of the seeds came from the high plateau.', '大部分种子来自这片高原。', 'Scientists', 23, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the Qinghai-Tibet Plateau', NULL, 'sufe');
