INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plain', 'n.', '/pleɪn/', '平原', 'The plateau is a large elevated plain.', '这片高原是一大片高出地面的平原。', 'Scientists', 25, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a flat plain', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'challenging', 'adj.', '/ˈtʃælɪndʒɪŋ/', '有挑战性的；困难的', 'Collecting seeds at that height was very challenging.', '在那样的高度采集种子非常有挑战性。', 'Scientists', 26, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a challenging task', NULL, 'sufe');
