INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'persist', 'v.', '/pəˈsɪst/', '坚持；持续', 'Despite all the hardships, the team persisted.', '尽管历经种种艰难，团队仍坚持了下来。', 'Scientists', 30, 0, 'senior', 'wordlist', 'elective2', 'U1', 'persist in', NULL, 'sufe');
