INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'medical', 'adj.', '/ˈmedɪkl/', '医学的；医疗的', 'Stored seeds may bring medical value in the future.', '储存的种子未来可能带来医学价值。', 'Scientists', 38, 0, 'senior', 'wordlist', 'elective2', 'U1', 'medical value', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disease', 'n.', '/dɪˈziːz/', '疾病', 'Hawking was found to have a serious disease at 21.', '霍金在21岁时被查出患有一种严重的疾病。', 'Scientists', 39, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a serious disease', NULL, 'sufe');
