INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'potential', 'n.', '/pəˈtenʃl/', '潜力；可能性', 'He feared he would never reach his full potential.', '他担心自己永远无法发挥全部潜力。', 'Scientists', 42, 0, 'senior', 'wordlist', 'elective2', 'U1', 'reach one''s potential', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'achievement', 'n.', '/əˈtʃiːvmənt/', '成就；成绩', 'His scientific achievement amazed the whole world.', '他的科学成就令全世界惊叹。', 'Scientists', 43, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a great achievement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'satellite', 'n.', '/ˈsætəlaɪt/', '卫星', 'Today computers help to guide satellites in space.', '如今计算机帮助引导太空中的卫星。', 'Scientists', 44, 0, 'senior', 'wordlist', 'elective2', 'U1', 'guide a satellite', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'process', 'v.', '/ˈprəʊses/', '处理；加工', 'Modern computers can process information in seconds.', '现代计算机能在几秒内处理信息。', 'Scientists', 45, 0, 'senior', 'wordlist', 'elective2', 'U1', 'process information', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impossible', 'adj.', '/ɪmˈpɒsəbl/', '不可能的', 'Decades ago, landing on the moon seemed impossible.', '几十年前，登月似乎是不可能的。', 'Scientists', 46, 0, 'senior', 'wordlist', 'elective2', 'U1', 'seem impossible', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suffering', 'n.', '/ˈsʌfərɪŋ/', '苦难；痛苦', 'Hawking turned his suffering into great achievements.', '霍金把他的苦难化为了伟大的成就。', 'Scientists', 47, 0, 'senior', 'wordlist', 'elective2', 'U1', 'great suffering', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'curiosity', 'n.', '/ˌkjʊəriˈɒsəti/', '好奇心', 'Curiosity is one of the most important qualities of a scientist.', '好奇心是科学家最重要的品质之一。', 'Scientists', 48, 0, 'senior', 'wordlist', 'elective2', 'U1', 'full of curiosity', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u1.01', '①-ing 形式作表语(说明事物的性质/命名活动)', 'A2', 11, '上外版选择性必修第二册 U1 — -ing 形式跟在 be/seem/sound/look 等系动词后作表语：①说明主语(事物/想法)令人产生某种感受，如 The findings were amazing；②在 ''one''s job/dream/task is + V-ing'' 中说明所从事的活动，如 His job is studying animals。', 1, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u1.02', '②-ed 形式作表语(说明人的感受/事物的状态)', 'A2', 11, '上外版选择性必修第二册 U1 — -ed 形式跟在 be/feel/seem/get/look/remain 等系动词后作表语，说明主语(多为人)的感受或事物所处的被动状态，如 The scientists were amazed；All these mysteries remain unsolved。', 2, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u1.03', '③-ing 还是 -ed(看主语)', 'A2', 11, '上外版选择性必修第二册 U1 — 判断用 -ing 还是 -ed 作表语：主语是引起感受的事物→用 -ing(exciting)；主语是产生感受的人→用 -ed(excited)。', 3, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The results of the experiment were really ____.', 'amazing', 'amazed', 'amaze', 'amazes', 'A', '主语 results 是引起感受的事物，用 -ing 形式作表语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'To young students, the idea of space travel sounds truly ____.', 'fascinated', 'fascinating', 'fascinate', 'fascinates', 'B', '主语 idea 是事物，令人着迷，用 -ing 形式。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The professor''s lecture on viruses was very ____.', 'inspired', 'inspire', 'inspiring', 'inspires', 'C', '主语 lecture 是事物，给人启发，用 -ing 形式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The new discovery about DNA seemed quite ____.', 'surprised', 'surprise', 'surprises', 'surprising', 'D', '主语 discovery 是事物，令人惊讶，用 -ing 形式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'For many people, the plan to land on Mars is ____.', 'exciting', 'excited', 'excite', 'excites', 'A', '主语 plan 是事物，令人激动，用 -ing 形式。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The strange data we collected last night looked rather ____.', 'puzzled', 'puzzling', 'puzzle', 'puzzles', 'B', '主语 data 是事物，令人困惑，用 -ing 形式。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The story of the female scientist was deeply ____.', 'moved', 'move', 'moving', 'moves', 'C', '主语 story 是事物，感人，用 -ing 形式。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'Watching the rocket take off was absolutely ____.', 'thrilled', 'thrill', 'thrills', 'thrilling', 'D', '主语(动名词短语)是事物，令人激动，用 -ing 形式。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The result of his patent application was ____.', 'disappointing', 'disappointed', 'disappoint', 'disappoints', 'A', '主语 result 是事物，令人失望，用 -ing 形式。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The way she never gave up is truly ____.', 'encouraged', 'encouraging', 'encourage', 'encourages', 'B', '主语(the way 从句)是事物，给人鼓舞，用 -ing 形式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The science fair this year was very ____.', 'interested', 'interest', 'interesting', 'interests', 'C', '主语 science fair 是事物，有趣，用 -ing 形式。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The strange noise from the old machine was a little ____.', 'worried', 'worry', 'worries', 'worrying', 'D', '主语 noise 是事物，令人担心，用 -ing 形式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'Her dream job is ____ new planets in deep space.', 'exploring', 'explored', 'explore', 'explores', 'A', '''job is + V-ing'' 用 -ing 形式作表语，说明所从事的活动。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'One key part of his work is ____ seeds for the national seed bank.', 'collected', 'collecting', 'collect', 'collects', 'B', '''part of work is + V-ing''，用 -ing 形式说明活动。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'A biologist''s daily task is ____ living things very closely.', 'observed', 'observe', 'observing', 'observes', 'C', '''task is + V-ing''，用 -ing 形式作表语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'My goal this year is ____ how viruses spread among plants.', 'discovered', 'discover', 'discovers', 'discovering', 'D', '''goal is + V-ing''，用 -ing 形式说明活动。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'His real passion is ____ machines that can help sick people.', 'inventing', 'invented', 'invent', 'invents', 'A', '''passion is + V-ing''，用 -ing 形式作表语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'The team''s main duty is ____ the rare seeds for the future.', 'protected', 'protecting', 'protect', 'protects', 'B', '''duty is + V-ing''，用 -ing 形式说明活动。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'Her main job on the team is ____ how the animal reacts in space.', 'described', 'describe', 'describing', 'describes', 'C', '''job is + V-ing''，用 -ing 形式作表语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.01'), 'A good scientist''s habit is ____ every result with great care.', 'examined', 'examine', 'examines', 'examining', 'D', '''habit is + V-ing''，用 -ing 形式说明活动。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'When the monkeys survived, the scientists were ____.', 'amazed', 'amazing', 'amaze', 'amazes', 'A', '主语 scientists 是产生感受的人，用 -ed 形式作表语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Hawking felt ____ when he first learned of his illness.', 'frightening', 'frightened', 'frighten', 'frightens', 'B', '主语 Hawking 是人，感到害怕，用 -ed 形式。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The students were ____ at the news of the science prize.', 'exciting', 'excite', 'excited', 'excites', 'C', '主语 students 是人，感到激动，用 -ed 形式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Professor Chen looked ____ at the failed results.', 'disappointing', 'disappoint', 'disappoints', 'disappointed', 'D', '主语 Professor Chen 是人，感到失望，用 -ed 形式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Franklin''s parents seemed ____ about her choice at first.', 'worried', 'worrying', 'worry', 'worries', 'A', '主语 parents 是人，感到担心，用 -ed 形式。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'We were all ____ by her courage in the face of hardship.', 'inspiring', 'inspired', 'inspire', 'inspires', 'B', '主语 we 是人，受到鼓舞，用 -ed 形式。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The young researcher felt ____ when the data made no sense.', 'puzzling', 'puzzle', 'puzzled', 'puzzles', 'C', '主语 researcher 是人，感到困惑，用 -ed 形式。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Everyone in the lab was ____ with the final result.', 'satisfying', 'satisfy', 'satisfies', 'satisfied', 'D', '主语 everyone 是人，感到满意，用 -ed 形式。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The visitors were deeply ____ by the scientist''s life story.', 'moved', 'moving', 'move', 'moves', 'A', '主语 visitors 是人，被打动，用 -ed 形式。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'She became ____ in biology when she was only fifteen.', 'interesting', 'interested', 'interest', 'interests', 'B', '主语 she 是人，对生物学感兴趣，用 -ed 形式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The whole class was ____ to hear that the animals survived in space.', 'surprising', 'surprise', 'surprised', 'surprises', 'C', '主语 class(指人)是产生感受的一方，用 -ed 形式。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'After the long climb, Zhong''s team felt completely ____.', 'exhausting', 'exhaust', 'exhausts', 'exhausted', 'D', '主语 team(指人)感到精疲力竭，用 -ed 形式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'He was ____ by the warm support of his fellow scientists.', 'touched', 'touching', 'touch', 'touches', 'A', '主语 he 是人，被感动，用 -ed 形式。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The children looked ____ during the whole science show.', 'fascinating', 'fascinated', 'fascinate', 'fascinates', 'B', '主语 children 是人，被吸引，用 -ed 形式。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Many girls feel ____ to study science by Franklin''s example.', 'encouraging', 'encourage', 'encouraged', 'encourages', 'C', '主语 girls 是人，受到鼓励，用 -ed 形式。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'For many years, the mystery of DNA remained ____.', 'unsolving', 'unsolve', 'unsolves', 'unsolved', 'D', 'remain 后用 -ed 形式作表语，说明谜团''未被解开''的状态。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Zhong Yang was completely ____ to his work in Tibet.', 'devoted', 'devoting', 'devote', 'devotes', 'A', 'be devoted to 用 -ed 形式作表语，表示''专注于''。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The biologists were ____ to find the old seeds still alive.', 'delighting', 'delighted', 'delight', 'delights', 'B', '主语 biologists 是人，感到高兴，用 -ed 形式。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'Her important work went ____ for many years.', 'unnoticing', 'unnotice', 'unnoticed', 'unnotices', 'C', 'go 后用 -ed 形式作表语，表示''未被注意''的状态。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.02'), 'The audience was ____ by the documentary about Franklin.', 'impressing', 'impress', 'impresses', 'impressed', 'D', '主语 audience 是人，被打动，用 -ed 形式。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The experiment was ____, so everyone wanted to try it themselves.', 'exciting', 'excited', 'excite', 'excites', 'A', '主语 experiment 是事物，令人激动，用 -ing 形式。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'After the long test, the students felt ____ and went home to rest.', 'tiring', 'tired', 'tire', 'tires', 'B', '主语 students 是人，感到疲惫，用 -ed 形式。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The lecture about black holes was ____ from start to finish.', 'fascinated', 'fascinate', 'fascinating', 'fascinates', 'C', '主语 lecture 是事物，令人着迷，用 -ing 形式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The professor was ____ by the strange results on the screen.', 'puzzling', 'puzzle', 'puzzles', 'puzzled', 'D', '主语 professor 是人，感到困惑，用 -ed 形式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The news about the Nobel Prize was ____ to all of us.', 'surprising', 'surprised', 'surprise', 'surprises', 'A', '主语 news 是事物，令人惊讶，用 -ing 形式。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'We were ____ to hear how she never gave up on her dream.', 'inspiring', 'inspired', 'inspire', 'inspires', 'B', '主语 we 是人，受到鼓舞，用 -ed 形式。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'Collecting seeds at high altitude is ____ work for the team.', 'tired', 'tire', 'tiring', 'tires', 'C', '修饰 work(事物)、说明其令人劳累，用 -ing 形式。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The young girl was very ____ in how plants grow.', 'interesting', 'interest', 'interests', 'interested', 'D', '主语 girl 是人，感兴趣，用 -ed 形式。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The final result of the long study was rather ____.', 'disappointing', 'disappointed', 'disappoint', 'disappoints', 'A', '主语 result 是事物，令人失望，用 -ing 形式。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'Franklin felt ____ when others took the credit for her work.', 'discouraging', 'discouraged', 'discourage', 'discourages', 'B', '主语 Franklin 是人，感到气馁，用 -ed 形式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The scientist''s life story is truly ____.', 'moved', 'move', 'moving', 'moves', 'C', '主语 story 是事物，感人，用 -ing 形式。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The whole team looked ____ after the long journey to the mountains.', 'exhausting', 'exhaust', 'exhausts', 'exhausted', 'D', '主语 team(指人)感到精疲力竭，用 -ed 形式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The idea of one day living on Mars sounds ____.', 'amazing', 'amazed', 'amaze', 'amazes', 'A', '主语 idea 是事物，令人惊叹，用 -ing 形式。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The children were ____ by the loud noise from the rocket.', 'frightening', 'frightened', 'frighten', 'frightens', 'B', '主语 children 是人，感到害怕，用 -ed 形式。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'Her speech about female scientists was very ____.', 'encouraged', 'encourage', 'encouraging', 'encourages', 'C', '主语 speech 是事物，给人鼓舞，用 -ing 形式。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'Everyone was ____ with the success of the experiment.', 'pleasing', 'please', 'pleases', 'pleased', 'D', '主语 everyone 是人，感到高兴，用 -ed 形式。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The data from the spaceship looked ____ at first.', 'confusing', 'confused', 'confuse', 'confuses', 'A', '主语 data 是事物，令人困惑，用 -ing 形式。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The students seemed ____ during the long, dull lecture.', 'boring', 'bored', 'bore', 'bores', 'B', '主语 students 是人，感到无聊，用 -ed 形式。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'Watching the rare seeds finally grow was deeply ____.', 'rewarded', 'reward', 'rewarding', 'rewards', 'C', '主语(动名词短语)是事物，令人有收获感，用 -ing 形式。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U1' AND code='se2u1.03'), 'The biologist was ____ to see her work help so many people.', 'delighting', 'delight', 'delights', 'delighted', 'D', '主语 biologist 是人，感到欣喜，用 -ed 形式。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Saving Seeds for the Future', 'Zhong Yang was a biology professor who gave much of his life to collecting plant seeds on the high Qinghai-Tibet Plateau. He believed that seeds were a treasure for the years to come. A seed bank, he explained, keeps seeds safe and may one day be useful for medicine or farming. It also protects the rich variety of plant life on our planet. The work was far from easy. Zhong and his students walked huge distances every year, often climbing higher than four thousand metres. The weather changed quickly, and they sometimes fell ill because of plant allergies. To save time, they ate only one simple meal a day. Yet they never stopped. Zhong also cared deeply about education, so he helped build new science programmes at Tibet University. Even after a serious illness, he kept working until a car accident took his life in 2017. He once said that work which helps others is always worth the price.', '人物·钟扬与种子库', 159, '[{"q":"Why did Zhong Yang think the seeds were so important?","answer":"A","options":["They might be useful for medicine and farming later on.","They were easy to sell for a high price.","They could replace every modern plant.","They were only useful as food for animals."],"explanation":"原文说种子库的种子''may one day be useful for medicine or farming''的转述。"},{"q":"What made the seed-collecting work so hard?","answer":"B","options":["A lack of money to buy seeds.","Long walks, high mountains, fast weather changes and illness.","Too many helpers on the team.","The seeds were too heavy to carry."],"explanation":"原文提到走长路、登高山、天气多变、因过敏生病等困难的概括。"},{"q":"Besides science, what else did Zhong care about?","answer":"A","options":["Improving education in Tibet.","Becoming rich and famous.","Building a large factory.","Travelling around the world for fun."],"explanation":"原文 ''cared deeply about education… build new science programmes'' 的转述。"}]'::jsonb, '[{"word":"plateau","cn":"高原"},{"word":"variety","cn":"多样性"},{"word":"allergy","cn":"过敏"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Woman Behind the DNA Photo', 'Rosalind Franklin was a British scientist who helped the world understand the shape of DNA. Using a special X-ray method, she produced a famous image that showed important clues about its structure. She was careful and patient, and she wanted more evidence before announcing anything. While she waited, two other scientists got hold of her data without asking. Soon they published a model of DNA that was built on her photograph. Years later, those scientists won a great prize, but Franklin received almost no credit for the key information she had given them. Life in science was not fair to her. As the only woman on the project, she could not even share lunch with the male scientists or join their discussions after work. Still, she never lost heart. She took up every challenge so that she could do what she loved most. Sadly, she fell ill and died young, before the world fully understood how much it owed her.', '人物·罗莎琳·富兰克林', 160, '[{"q":"What did Franklin''s famous X-ray image help to show?","answer":"B","options":["A cure for a common disease.","Clues about the shape of DNA.","How to build a faster computer.","The age of an ancient rock."],"explanation":"原文 ''showed important clues about its structure''(指 DNA)的转述。"},{"q":"Why did she wait before announcing her findings?","answer":"C","options":["She had forgotten her own results.","She was told to keep them secret.","She wanted to be sure by collecting more proof.","She did not believe in her own work."],"explanation":"原文 ''careful and patient… wanted more evidence'' 的转述。"},{"q":"How does the writer present Franklin''s treatment in science?","answer":"D","options":["As easy and full of rewards.","As fair and equal to everyone.","As unimportant to her career.","As unfair, especially because she was a woman."],"explanation":"原文描述她不被尊重、得不到认可，体现作者认为对她不公平。"}]'::jsonb, '[{"word":"evidence","cn":"证据"},{"word":"credit","cn":"认可"},{"word":"data","cn":"数据"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Mind That Never Stopped', 'When Stephen Hawking was twenty-one, doctors found that he had a serious disease and told him he would live only a few years. The news was hard to accept, and at first he thought his life was over. But Hawking proved the doctors wrong in a remarkable way. He went on living and working for more than fifty years. As the illness grew worse, it slowly took away his power to move and even to speak. With the help of a special machine, he could still share his ideas with the world, and he wrote books that millions of people read. Looking back near the end of his life, he wrote that he could feel quietly satisfied with all he had done. His story shows that a strong mind can be far more powerful than a weak body. Today many young people are still inspired by his courage and his refusal to give up, no matter how difficult life became.', '人物·史蒂芬·霍金', 160, '[{"q":"What did the doctors tell Hawking when he was twenty-one?","answer":"A","options":["That he would only live for a few more years.","That his disease was not serious at all.","That he should stop studying science.","That he would soon be completely cured."],"explanation":"原文 ''told him he would live only a few years'' 的转述。"},{"q":"How did Hawking keep sharing his ideas after losing his speech?","answer":"B","options":["By writing with his own hand.","By using a special machine.","By asking others to speak for him.","By giving up his research."],"explanation":"原文 ''with the help of a special machine, he could still share his ideas'' 的转述。"},{"q":"What main message does the writer want readers to take away?","answer":"C","options":["Good health is the only key to success.","Science is too hard for most people.","A determined mind can be stronger than a weak body.","Fame matters more than courage."],"explanation":"末段 ''a strong mind can be far more powerful than a weak body'' 的转述。"}]'::jsonb, '[{"word":"disease","cn":"疾病"},{"word":"satisfied","cn":"满意的"},{"word":"inspire","cn":"鼓舞"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Twice a Nobel Winner', 'Marie Curie is one of the most famous scientists in history, and she is remembered for a very rare achievement. She won the Nobel Prize not once but twice, in two different areas of science. This had never been done by a woman before her. Curie spent long hours in a cold, poorly equipped room, studying materials that few people understood at the time. The work was slow and sometimes dangerous, yet she carried on with great patience. Like many women of her day, she had to prove herself again and again in a world that did not expect women to be scientists. She believed that nothing in life should be feared; it should only be understood. Her discoveries opened new doors in both physics and medicine, and they continue to help doctors and researchers today. Curie''s story reminds us that curiosity, hard work and courage matter just as much as natural talent.', '人物·居里夫人', 153, '[{"q":"Why is Marie Curie''s achievement described as rare?","answer":"D","options":["She was the youngest scientist ever.","She never published any work.","She worked completely alone all her life.","She earned the Nobel Prize twice, in two separate fields of science."],"explanation":"原文 ''won the Nobel Prize not once but twice, in two different areas'' 的转述。"},{"q":"What were her working conditions like?","answer":"A","options":["A cold room with poor equipment.","A warm and modern laboratory.","A busy and crowded factory.","A quiet seaside house."],"explanation":"原文 ''a cold, poorly equipped room'' 的转述。"},{"q":"According to the last lines, what does Curie''s story teach us?","answer":"B","options":["Only talent decides success.","Courage and hard work count for as much as talent does.","Science is best left to men.","Money is the key to discovery."],"explanation":"末句 ''curiosity, hard work and courage matter just as much as natural talent'' 的转述。"}]'::jsonb, '[{"word":"achievement","cn":"成就"},{"word":"patience","cn":"耐心"},{"word":"curiosity","cn":"好奇心"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Life Among the Chimpanzees', 'Jane Goodall is a scientist who is famous for her work on animal behaviour, especially that of chimpanzees. As a young woman, she travelled to Africa with little training but a great love of animals. Instead of watching the animals from far away, she lived close to them in the forest for many years. She gave the chimpanzees names rather than numbers, and she watched them patiently, day after day. Slowly she discovered that they could make and use simple tools, something many people had believed only humans could do. Her findings surprised scientists around the world and changed the way we think about animals. Goodall also learned that protecting wild animals means protecting the places where they live. Today she travels widely, telling young people that every one of us can make a difference. Her story shows that careful watching, patience and respect can lead to discoveries that books alone could never give.', '人物·简·古道尔', 154, '[{"q":"How did Goodall choose to study the chimpanzees?","answer":"C","options":["By keeping them in a small cage.","By reading about them in books only.","By living near them in the wild for several years.","By watching them on television."],"explanation":"原文 ''lived close to them in the forest for many years'' 的转述。"},{"q":"What surprising discovery did she make?","answer":"D","options":["Chimpanzees can speak human languages.","Chimpanzees never eat plants.","Chimpanzees cannot live in groups.","Chimpanzees are able to make and use basic tools."],"explanation":"原文 ''they could make and use simple tools'' 的转述。"},{"q":"What does Goodall tell young people today?","answer":"A","options":["That each person can make a difference.","That only experts can help animals.","That science is a waste of time.","That forests should be cut down."],"explanation":"原文 ''every one of us can make a difference'' 的转述。"}]'::jsonb, '[{"word":"behaviour","cn":"行为"},{"word":"tool","cn":"工具"},{"word":"patiently","cn":"耐心地"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Mother of Computer Software', 'Grace Hopper was one of the most important people in the early development of computer software. In her time, computers were huge machines that filled whole rooms, and very few people knew how to use them. Hopper believed that ordinary people should be able to give computers instructions using words that were easy to understand, not just difficult numbers. Many experts told her that this idea would never work, but she refused to give up. After years of patient effort, she helped create a new way of writing instructions that was much closer to everyday English. Her work made computers far easier to use and opened the door for the software we depend on today. Hopper was also a famous teacher who loved to encourage young people to try new things. She often said that the most dangerous phrase in any language is ''We have always done it this way.'' Her courage to question old habits changed the world of computing forever.', '人物·格蕾丝·霍珀', 162, '[{"q":"What did Hopper want ordinary people to be able to do?","answer":"B","options":["Build computers in their own homes.","Give computers instructions using easy words.","Sell computers around the world.","Stop using computers completely."],"explanation":"原文 ''give computers instructions using words that were easy to understand'' 的转述。"},{"q":"How did many experts react to her idea at first?","answer":"C","options":["They quickly agreed with her.","They asked her to lead them.","They thought it would never work.","They had never heard of computers."],"explanation":"原文 ''many experts told her that this idea would never work'' 的转述。"},{"q":"What does her favourite phrase about old habits suggest?","answer":"D","options":["We should always do things the same way.","Computers can never be improved.","New ideas are usually a mistake.","We should be ready to question the old way of doing things."],"explanation":"她认为''We have always done it this way''最危险，说明应敢于质疑旧习惯。"}]'::jsonb, '[{"word":"software","cn":"软件"},{"word":"instruction","cn":"指令"},{"word":"depend","cn":"依靠"}]'::jsonb, 2, 'elective2', 'U1', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Becoming a Scientist', 'When I was young, I was already very (1)____ about how the world works. I would spend hours (2)____ insects in the garden and asking endless questions. My parents were always (3)____ and bought me my first science book. After reading it, I felt (4)____ to learn much more. At school, my favourite (5)____ was biology, because it explained how living things grow. My teacher told us that a good scientist must stay (6)____ and never stop wondering. She also said that every great (7)____ began with a simple question. Slowly, I made up my mind to (8)____ science at university one day. I know the road ahead will be (9)____, but I am ready to work hard. In the future, I hope my own research will (10)____ many other people.', 131, 2, '[{"q":"1","answer":"A","options":["curious","careful","polite","quiet"],"explanation":"curious about 对……好奇。"},{"q":"2","answer":"B","options":["buying","watching","selling","hiding"],"explanation":"watching insects 观察昆虫。"},{"q":"3","answer":"C","options":["angry","bored","supportive","afraid"],"explanation":"supportive 支持的。"},{"q":"4","answer":"D","options":["tired","bored","scared","inspired"],"explanation":"feel inspired 受到鼓舞。"},{"q":"5","answer":"A","options":["subject","price","noise","weather"],"explanation":"favourite subject 最喜欢的科目。"},{"q":"6","answer":"B","options":["rich","patient","late","busy"],"explanation":"stay patient 保持耐心。"},{"q":"7","answer":"C","options":["price","noise","discovery","market"],"explanation":"great discovery 伟大的发现。"},{"q":"8","answer":"D","options":["sell","forget","drop","study"],"explanation":"study science 学习科学。"},{"q":"9","answer":"A","options":["hard","soft","late","empty"],"explanation":"the road will be hard 道路艰难。"},{"q":"10","answer":"B","options":["hurt","help","sell","lose"],"explanation":"help other people 帮助他人。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'A Visit to the Science Museum', 'Last spring, our class went to visit a science (1)____. The moment we walked in, I felt (2)____ by all the amazing machines. A robot could even (3)____ to our questions in English. In one room, we learned how a rocket is (4)____ into space. In another, a guide showed us a model of the human (5)____ powered by electricity. I was so (6)____ that I almost forgot to eat lunch. My friend Lin was most (7)____ in the part about space animals. We also watched a short (8)____ about famous scientists and their hard work. Before we left, each of us wrote down one science (9)____ we still wanted to answer. That trip made me want to (10)____ harder at my science lessons.', 124, 2, '[{"q":"1","answer":"C","options":["market","garden","museum","station"],"explanation":"science museum 科技馆。"},{"q":"2","answer":"D","options":["bored","tired","angry","amazed"],"explanation":"feel amazed 感到惊叹。"},{"q":"3","answer":"A","options":["reply","sleep","leave","cry"],"explanation":"reply to questions 回答问题。"},{"q":"4","answer":"B","options":["eaten","sent","sold","lost"],"explanation":"be sent into space 被送入太空。"},{"q":"5","answer":"C","options":["price","noise","body","season"],"explanation":"the human body 人体。"},{"q":"6","answer":"D","options":["bored","calm","quiet","excited"],"explanation":"so excited that 如此激动以至于。"},{"q":"7","answer":"A","options":["interested","afraid","sorry","late"],"explanation":"interested in 对……感兴趣。"},{"q":"8","answer":"B","options":["price","film","noise","market"],"explanation":"a short film 一部短片。"},{"q":"9","answer":"C","options":["price","machine","question","ticket"],"explanation":"a science question 一个科学问题。"},{"q":"10","answer":"D","options":["sleep","sell","hide","study"],"explanation":"study harder 更努力学习。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Why Science Needs Everyone', 'For a long time, science was seen as a (1)____ only for men. Many talented women were not (2)____ the same chances as men. Some were not even (3)____ to join important discussions. Yet a few brave women refused to give (4)____. They worked hard, often without any (5)____ for their efforts. One famous woman studied tiny living things under a (6)____ and helped others understand disease. Her careful (7)____ later became the base of many discoveries. Today we know that good ideas can come from (8)____, no matter who they are. Science becomes (9)____ when more kinds of people take part. That is why schools now (10)____ both boys and girls to dream of becoming scientists.', 117, 2, '[{"q":"1","answer":"A","options":["world","price","noise","market"],"explanation":"a world only for men 一个只属于男性的世界。"},{"q":"2","answer":"B","options":["sold","given","eaten","lost"],"explanation":"be given chances 被给予机会。"},{"q":"3","answer":"C","options":["sold","eaten","allowed","thrown"],"explanation":"be allowed to join 被允许加入。"},{"q":"4","answer":"D","options":["in","off","out","up"],"explanation":"give up 放弃。"},{"q":"5","answer":"A","options":["credit","noise","weather","price"],"explanation":"without any credit 没有任何认可。"},{"q":"6","answer":"B","options":["market","microscope","garden","station"],"explanation":"under a microscope 在显微镜下。"},{"q":"7","answer":"C","options":["price","noise","work","game"],"explanation":"her careful work 她细致的工作。"},{"q":"8","answer":"D","options":["nowhere","nothing","never","anyone"],"explanation":"come from anyone 来自任何人。"},{"q":"9","answer":"A","options":["stronger","weaker","smaller","shorter"],"explanation":"becomes stronger 变得更强大。"},{"q":"10","answer":"B","options":["stop","encourage","forbid","forget"],"explanation":"encourage…to dream 鼓励……去梦想。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Animals in Space', 'The first living things to travel into space were not people but (1)____. In the 1950s, scientists sent two monkeys high above the Earth. They wanted to find out what would (2)____ to living things during the trip. The monkeys (3)____ the journey, and the scientists were very glad. Later, a dog was (4)____ into space to travel around the Earth. Special tools (5)____ the animals'' heart rate and breathing. In this way, researchers slowly learned about the (6)____ of space travel on the body. These brave animals (7)____ the way for human astronauts. Without them, sending people into space would have been far more (8)____. Today, we (9)____ a lot to those early animal travellers. Their story reminds us that every great (10)____ takes courage and care.', 128, 2, '[{"q":"1","answer":"C","options":["books","prices","animals","songs"],"explanation":"not people but animals 不是人而是动物。"},{"q":"2","answer":"D","options":["sell","sleep","hide","happen"],"explanation":"what would happen 会发生什么。"},{"q":"3","answer":"A","options":["survived","lost","sold","forgot"],"explanation":"survived the journey 活过了旅程。"},{"q":"4","answer":"B","options":["eaten","sent","sold","dropped"],"explanation":"be sent into space 被送入太空。"},{"q":"5","answer":"C","options":["ate","sold","recorded","lost"],"explanation":"recorded the heart rate 记录心率。"},{"q":"6","answer":"D","options":["prices","noises","songs","effects"],"explanation":"the effects of space travel 太空旅行的影响。"},{"q":"7","answer":"A","options":["opened","closed","sold","lost"],"explanation":"opened the way 开辟了道路。"},{"q":"8","answer":"B","options":["cheap","dangerous","quiet","short"],"explanation":"far more dangerous 危险得多。"},{"q":"9","answer":"C","options":["sell","lose","owe","hide"],"explanation":"owe a lot to 把很多归功于。"},{"q":"10","answer":"D","options":["price","noise","market","step"],"explanation":"every great step 每一大步。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Stephen Hawking''s Spirit', 'Stephen Hawking was one of the greatest scientists of our (1)____. At the age of twenty-one, he was told that he had a serious (2)____. Doctors believed he would live only a few (3)____. But Hawking proved them (4)____. He went on working for more than fifty years. As the illness grew worse, he lost the (5)____ to move and to speak. Even so, he never (6)____ his research. With the help of a special machine, he could still (7)____ with the world. He once wrote that, looking back, he could feel (8)____ with his life. His story shows that a strong (9)____ can be more powerful than the body. Millions of people are still (10)____ by his courage today.', 120, 2, '[{"q":"1","answer":"A","options":["time","price","noise","market"],"explanation":"scientists of our time 我们这个时代的科学家。"},{"q":"2","answer":"B","options":["garden","disease","market","ticket"],"explanation":"a serious disease 一种严重的疾病。"},{"q":"3","answer":"C","options":["metres","prices","years","songs"],"explanation":"a few years 几年。"},{"q":"4","answer":"D","options":["right","late","busy","wrong"],"explanation":"prove them wrong 证明他们错了。"},{"q":"5","answer":"A","options":["ability","price","noise","weather"],"explanation":"the ability to move 行动的能力。"},{"q":"6","answer":"B","options":["sold","stopped","ate","lost"],"explanation":"never stopped his research 从未停止研究。"},{"q":"7","answer":"C","options":["sleep","leave","communicate","hide"],"explanation":"communicate with the world 与世界交流。"},{"q":"8","answer":"D","options":["angry","bored","afraid","satisfied"],"explanation":"feel satisfied 感到满意。"},{"q":"9","answer":"A","options":["mind","price","noise","market"],"explanation":"a strong mind 坚强的头脑。"},{"q":"10","answer":"B","options":["bored","inspired","tired","scared"],"explanation":"be inspired by 受到鼓舞。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'The Joy of Discovery', 'Many people think that science is just a (1)____ of hard facts to memorise. In fact, science begins with (2)____ — the simple wish to know why things happen. A good scientist looks at the world with (3)____ eyes and is never afraid to ask questions. When an experiment does not (4)____ as planned, that is not a failure but a chance to (5)____ something new. Some of the greatest discoveries came from a small (6)____ that no one expected. Of course, the work can be slow and (7)____, and answers do not come easily. But the moment when everything finally makes (8)____ is wonderful. That feeling is the real (9)____ that keeps scientists going. In the end, curiosity and patience matter just as (10)____ as intelligence.', 127, 2, '[{"q":"1","answer":"C","options":["price","song","set","ticket"],"explanation":"a set of facts 一堆事实。"},{"q":"2","answer":"D","options":["money","noise","weather","curiosity"],"explanation":"begins with curiosity 始于好奇心。"},{"q":"3","answer":"A","options":["curious","angry","sleepy","bored"],"explanation":"with curious eyes 用好奇的眼睛。"},{"q":"4","answer":"B","options":["sleep","work","sell","hide"],"explanation":"does not work as planned 没有按计划进行。"},{"q":"5","answer":"C","options":["lose","sell","learn","forget"],"explanation":"learn something new 学到新东西。"},{"q":"6","answer":"D","options":["price","song","ticket","detail"],"explanation":"a small detail 一个小细节。"},{"q":"7","answer":"A","options":["difficult","easy","cheap","short"],"explanation":"slow and difficult 缓慢而困难。"},{"q":"8","answer":"B","options":["noise","sense","price","money"],"explanation":"makes sense 讲得通。"},{"q":"9","answer":"C","options":["price","noise","reward","weather"],"explanation":"the real reward 真正的回报。"},{"q":"10","answer":"D","options":["little","few","many","much"],"explanation":"just as much as 与……同等重要。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 A Scientist I Admire', '上外版选择性必修第二册 U1 · dialogue', 3, 'A: Who is the scientist you admire most, Lily?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 What a Seed Bank Does', '上外版选择性必修第二册 U1 · passage', 2, 'A seed bank is a special place that keeps plant seeds safe.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Planning the Science Festival', '上外版选择性必修第二册 U1 · dialogue', 3, 'A: Our class needs to recommend a scientist for the science festival.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 The Story of Rosalind Franklin', '上外版选择性必修第二册 U1 · passage', 2, 'Rosalind Franklin was a British scientist who studied the structure of DNA.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 At the Science Fair', '上外版选择性必修第二册 U1 · dialogue', 3, 'A: This science fair is so crowded today!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 What Makes a Good Scientist', '上外版选择性必修第二册 U1 · passage', 2, 'What makes someone a good scientist? It is not only brain power.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a descriptive essay about exploring science(描写一次探索科学的经历)', 'An Unforgettable Science Experience', '你所在学校的科学社团下个月将庆祝成立四周年，邀请你写一篇英语短文，分享一次你探索科学的个人经历(可以是听的一次科学讲座、做的一个实验、参观科技馆、和朋友玩的科学游戏等)。要求:① 写清时间、地点和你做了什么;② 用感官细节(看到/听到/感到)和一句对话让描写生动;③ 表达你的感受。约100-120词。', 'Your school science society is celebrating its fourth anniversary next month. Write a short essay (about 100-120 words) sharing a personal experience of exploring science — a lecture you attended, an experiment you did, a visit to a science museum, or a science game you played. Make sure to: 1) say when and where it was and what you did; 2) use sensory details and at least one line of dialogue to make the writing vivid; 3) describe how you felt.', '["交代时间地点与所做的事(Last week, our class visited …)","用感官细节让画面生动(I saw … / I could hear … / It felt …)","用一句对话增添真实感(\"That''s so cool!\" I said.)","结尾表达感受(I left with a feeling of joy and wonder.)"]'::jsonb, 70, 100, 'Last week, our class visited a science fair, and I was so excited that I could hardly sleep the night before. The hall was crowded with students and bright with colourful models. What interested me most was a model of the human body powered by electricity. I could see the heart and lungs working clearly before my eyes. "That''s so cool!" I said, leaning closer. The boy who had built it glowed with pride. "I''m always fascinated by how our body works," he told me with a smile. The whole place was full of amazing inventions and curious faces. I left the fair with a feeling of joy and wonder, and I made up my mind to bring my own model rocket next year.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I was so excited that I could hardly sleep the night before.","What interested me most was a model of the human body powered by electricity.","The boy who had built it glowed with pride.","I left the fair with a feeling of joy and wonder."]'::jsonb, '[{"wrong":"The experiment was very interested.","correct":"The experiment was very interesting.","note":"主语是事物用 -ing 形式作表语。"},{"wrong":"I was so exciting that I could not sleep.","correct":"I was so excited that I could not sleep.","note":"主语是人用 -ed 形式作表语。"},{"wrong":"My dream is become a scientist.","correct":"My dream is becoming a scientist.","note":"''dream is + V-ing'' 用 -ing 形式作表语。"}]'::jsonb, '【探索科学经历·描写文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U1', '{"title":"-ing / -ed 形式作表语速查","intro":"动词的 -ing / -ed 形式可以跟在系动词后面作表语，说明主语的性质或状态。常见系动词:be, seem, get, look, become, appear, feel, remain。判断口诀:主语是引起感受的事物 → -ing;主语是产生感受的人 → -ed。","table":{"headers":["形式","用法 / 例句"],"rows":[["-ing(说明事物)","事物令人产生感受:The findings were amazing. / The story is moving."],["-ing(命名活动)","job/dream/task is + V-ing:His job is studying animals."],["-ed(说明人)","人产生感受:The scientists were amazed. / She felt excited."],["-ed(说明状态)","事物处于被动状态:All these mysteries remain unsolved. / He is devoted to his work."]]},"specialRules":[{"rule":"主语是物、令人产生某种感受 → 用 -ing","mark":"The result was disappointing.(令人失望)"},{"rule":"主语是人、自己产生某种感受 → 用 -ed","mark":"We were disappointed.(感到失望)"},{"rule":"''one''s job/dream/task is + 动名词'' 命名所做的事","mark":"Her dream is exploring space."},{"rule":"remain / go / be + -ed 说明事物的被动状态","mark":"The puzzle remained unsolved."}],"why":["-ing 表示''主动地、令人……''，所以用来形容引起感受的事物;-ed 表示''被……、感到……'',所以用来形容产生感受的人或处于被动状态的事物。同一动词两种形式不能混用。"],"gaokaoPoints":["interesting/interested、exciting/excited、moving/moved 等成对形容词的选择(看主语是物还是人),语法填空与改错高频。","系动词(be/seem/get/look/become/feel/remain)后接 -ing/-ed 作表语,而非简单进行时或被动语态——靠主语意义判断。"],"examVsReal":[{"exam":"The news was surprising.（考试/书面）","real":"The news? Wow, so surprising!","note":"考试要求按主语严格区分 -ing/-ed;口语里常省略系动词、直接用形容词。"},{"exam":"His job is collecting seeds.（考试）","real":"His job is to collect seeds. / He collects seeds.","note":"考试可用 V-ing 作表语;真实表达里 ''is to do'' 与一般现在时同样自然。"}]}'::jsonb, 'sufe');
